beforeSaveCustomScript:
name = string\trim(string\concatenate(firstName, ' ', lastName));

if (taxCode != null) {
    taxCode = string\upperCase(string\trim(taxCode));
}

if (province != null) {
    province = string\upperCase(string\trim(province));
}

$today = datetime\today();
$startOk = ifThenElse(joinDate == null, true, joinDate <= $today);
$endOk = ifThenElse(leaveDate == null, true, leaveDate >= $today);
status = ifThenElse($startOk && $endOk, 'Active', 'Inactive');
